--
-- Triggers `work_permit_fees`
--
DELIMITER $$
CREATE TRIGGER `before_work_permit_insert` BEFORE INSERT ON `work_permit_fees` FOR EACH ROW BEGIN
    DECLARE emp_status VARCHAR(10);
    DECLARE emp_nationality VARCHAR(50);

    -- Fetch employment_status and nationality for the employee
    SELECT employment_status, nationality
    INTO emp_status, emp_nationality
    FROM employees
    WHERE emp_no = NEW.emp_no;

    -- Check if the employee is active and not Maldivian
    IF emp_status != 'Active' OR emp_nationality = 'MALDIVIAN' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid employee: Employee must be Active and non-Maldivian';
    END IF;
END
$$
DELIMITER ;

