DELIMITER $$
--
-- Events
--
CREATE DEFINER=`rccmgvfd`@`localhost` EVENT `update_medical_examinations` ON SCHEDULE EVERY 1 DAY STARTS '2025-03-17 00:00:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    SELECT e.emp_no, 'Not Assigned', CURDATE(), 'Pending'
    FROM employees e
    LEFT JOIN medical_examinations m ON e.emp_no = m.employee_id
    WHERE e.employment_status = 'Active'
    AND e.nationality != 'MALDIVIAN'
    AND m.employee_id IS NULL;
END$$

DELIMITER ;
